function transform(message, context) {
  function esc(v) {
    if (v === null || v === undefined) return '';
    return String(v)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }
  var r = message.payload;
  var x = [];
  x.push('  <user>');
  x.push('    <record_type>PUBLIC</record_type>');
  x.push('    <primary_id>' + esc(r.primary_id) + '</primary_id>');
  x.push('    <first_name>' + esc(r.first_name) + '</first_name>');
  if (r.middle_initial) x.push('    <middle_name>' + esc(r.middle_initial) + '</middle_name>');
  x.push('    <last_name>' + esc(r.last_name) + '</last_name>');
  x.push('    <pin_number></pin_number>');
  if (r.user_title) x.push('    <user_title>' + esc(r.user_title) + '</user_title>');
  x.push('    <user_group desc="' + esc(r.user_group_desc) + '">' + esc(r.user_group_code) + '</user_group>');
  x.push('    <preferred_language desc="English">en</preferred_language>');
  if (r.birth_date) x.push('    <birth_date>' + esc(r.birth_date) + 'Z</birth_date>');
  x.push('    <expiry_date>' + esc(r.expiry_date) + 'Z</expiry_date>');
  x.push('    <purge_date>' + esc(r.expiry_date) + 'Z</purge_date>');
  x.push('    <user_identifiers>');
  x.push('      <user_identifier segment_type="External">');
  x.push('        <id_type desc="01">01</id_type>');
  x.push('        <value>' + esc(r.external_id) + '</value>');
  x.push('        <status>ACTIVE</status>');
  x.push('      </user_identifier>');
  x.push('    </user_identifiers>');
  x.push('    <contact_info>');
  if (r.address_line_1) {
    x.push('      <addresses>');
    x.push('        <address preferred="true">');
    x.push('          <line1>' + esc(r.address_line_1) + '</line1>');
    x.push('          <city>' + esc(r.city) + '</city>');
    x.push('          <state_province>' + esc(r.state) + '</state_province>');
    x.push('          <postal_code>' + esc(r.zip) + '</postal_code>');
    x.push('          <country>' + esc(r.country) + '</country>');
    x.push('          <address_types>');
    x.push('            <address_type desc="home">home</address_type>');
    x.push('          </address_types>');
    x.push('        </address>');
    x.push('      </addresses>');
  }
  x.push('      <emails>');
  x.push('        <email preferred="true">');
  x.push('          <email_address>' + esc(r.email_address) + '</email_address>');
  x.push('          <email_types>');
  x.push('            <email_type desc="personal">personal</email_type>');
  x.push('          </email_types>');
  x.push('        </email>');
  x.push('      </emails>');
  x.push('    </contact_info>');
  x.push('  </user>');
  message.payload = x.join('\n');
  return message;
}

function transform(message, context) {
  var users = Array.isArray(message.payload) ? message.payload : [message.payload];
  var now = new Date();
  function p2(n) { return ('0' + n).slice(-2); }
  var ts = '' + now.getFullYear() + p2(now.getMonth() + 1) + p2(now.getDate())
         + '_' + p2(now.getHours()) + p2(now.getMinutes()) + p2(now.getSeconds());
  var xmlName = 'report_student_' + ts + '.xml';
  var zipName = 'report_student_' + ts + '.zip';
  context.set('xmlName', xmlName);
  context.set('zipName', zipName);
  var dir = context.almaSftpPath || '/';
  if (dir.slice(-1) !== '/') dir += '/';
  context.set('outfile', dir + zipName);
  message.payload = '<?xml version="1.0" encoding="utf-8"?>\n<users>\n'
                  + users.join('\n')
                  + '\n</users>';
  return message;
}

function transform(message, context) {
  message.payload = {
    files: [context.get('xmlName')]
  };
  return message;
}
